1	package org.springframework.samples.petclinic.security;
2	
3	import org.springframework.beans.factory.annotation.Autowired;
4	import org.springframework.http.ResponseEntity;
5	import org.springframework.security.authentication.AuthenticationManager;
6	import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
7	import org.springframework.security.core.Authentication;
8	import org.springframework.security.core.userdetails.UserDetails;
9	import org.springframework.web.bind.annotation.*;
10	
11	import io.swagger.v3.oas.annotations.Operation;
12	import io.swagger.v3.oas.annotations.Parameter;
13	import io.swagger.v3.oas.annotations.media.Content;
14	import io.swagger.v3.oas.annotations.media.Schema;
15	import io.swagger.v3.oas.annotations.responses.ApiResponse;
16	import io.swagger.v3.oas.annotations.responses.ApiResponses;
17	import io.swagger.v3.oas.annotations.tags.Tag;
18	
19	import java.util.HashMap;
20	import java.util.Map;
21	
22	@RestController
23	@RequestMapping("/api/auth")
24	@CrossOrigin(origins = "*")
25	@Tag(name = "Authentication", description = "Authentication management API")
26	public class AuthController {
27	
28		@Autowired
29		private AuthenticationManager authenticationManager;
30	
31		@Autowired
32		private JwtUtil jwtUtil;
33	
34		@Autowired
35		private CustomUserDetailsService userDetailsService;
36	
37		@PostMapping("/login")
38		@Operation(summary = "User login", description = "Authenticate user and return JWT token")
39		@ApiResponses(value = {
40				@ApiResponse(responseCode = "200", description = "Login successful",
41						content = @Content(schema = @Schema(implementation = Map.class))),
42				@ApiResponse(responseCode = "400", description = "Invalid credentials",
43						content = @Content(schema = @Schema(implementation = Map.class))) })
44		public ResponseEntity<?> login(@RequestBody LoginRequest loginRequest) {
45			try {
46				Authentication authentication = authenticationManager.authenticate(
47						new UsernamePasswordAuthenticationToken(loginRequest.getUsername(), loginRequest.getPassword()));
48	
49				UserDetails userDetails = userDetailsService.loadUserByUsername(loginRequest.getUsername());
50				String token = jwtUtil.generateToken(userDetails.getUsername());
51	
52				Map<String, Object> response = new HashMap<>();
53				response.put("token", token);
54				response.put("type", "Bearer");
55				response.put("username", userDetails.getUsername());
56				response.put("expiresIn", 86400); // 24 hours in seconds
57	
58				return ResponseEntity.ok(response);
59			}
60			catch (Exception e) {
61				Map<String, String> error = new HashMap<>();
62				error.put("error", "Invalid username or password");
63				return ResponseEntity.badRequest().body(error);
64			}
65		}
66	
67		@PostMapping("/validate")
68		@Operation(summary = "Validate token", description = "Validate JWT token and return user information")
69		@ApiResponses(value = { @ApiResponse(responseCode = "200", description = "Token validation result",
70				content = @Content(schema = @Schema(implementation = Map.class))) })
71		public ResponseEntity<?> validateToken(
72				@RequestHeader("Authorization") @Parameter(description = "Bearer token") String authHeader) {
73			try {
74				if (authHeader != null && authHeader.startsWith("Bearer ")) {
75					String token = authHeader.substring(7);
76					String username = jwtUtil.extractUsername(token);
77	
78					if (jwtUtil.validateToken(token, username)) {
79						Map<String, Object> response = new HashMap<>();
80						response.put("valid", true);
81						response.put("username", username);
82						return ResponseEntity.ok(response);
83					}
84				}
85	
86				Map<String, Object> response = new HashMap<>();
87				response.put("valid", false);
88				return ResponseEntity.ok(response);
89			}
90			catch (Exception e) {
91				Map<String, Object> response = new HashMap<>();
92				response.put("valid", false);
93				response.put("error", "Invalid token");
94				return ResponseEntity.ok(response);
95			}
96		}
97	
98		@Schema(description = "Login request")
99		public static class LoginRequest {
100	
101			@Schema(description = "Username", example = "admin")
102			private String username;
103	
104			@Schema(description = "Password", example = "password")
105			private String password;
106	
107			public String getUsername() {
108				return username;
109			}
110	
111			public void setUsername(String username) {
112				this.username = username;
113			}
114	
115			public String getPassword() {
116				return password;
117			}
118	
119			public void setPassword(String password) {
120				this.password = password;
121			}
122	
123		}
124	
125	}
