		if (lastName != null && !lastName.isEmpty()) {
			return owners.stream()
				.filter(owner -> owner.getLastName().toLowerCase().startsWith(lastName.toLowerCase()))
				.toList();
		}
		return owners;
	}

	@GetMapping("/{ownerId}")
